%root_path = fileparts(mfilename("fullpath"));
%root_path = pwd;

% retrieve selected cuts used for further fitting
[GH_FFCutsFits,CutFitFileGH] = recover_selected_cuts('GH_FFCutsFits','e:\SHARE\Fe\Data\analysis\07_fit_with_multicut_allJ\sel_cuts');

%%
fn = fieldnames(GH_FFCutsFits);
%nf = 11
%for nf = 2:numel(fn)
%selectCuts = fn{nf};
selectCuts = 'Ei400_off020GH001minFF';
if ismember(selectCuts(1:3),{'msk','dat'})||...
        contains(selectCuts,'all_fit_par')
    %continue
    error('Can not fit field: %s',selectCuts);
end

fprintf('***********************************\n'); %[output:0d7893e6]
fprintf('Processing cuts: %s \n', selectCuts); %[output:82c70c1b]
fprintf('***********************************\n'); %[output:0466c93b]

cuts_list = GH_FFCutsFits.(selectCuts);
if ~iscell(cuts_list)
    cuts_list = {cuts_list};
end
if contains(selectCuts,'Ei200')
    min_Ei = 30;
    mi = maps_instrument(200,600,'S');
end
if contains(selectCuts,'Ei400')
    min_Ei = 40;
    mi = maps_instrument(401,600,'S');
end
if contains(selectCuts,'Ei800')
    min_Ei =70;
    mi = maps_instrument(786,600,'S');
end
sample=IX_sample(true,[1,0,0],[0,1,0],'cuboid',[0.04,0.03,0.02]);
for j=1:numel(cuts_list) %[output:group:6c4996ce]
    cuts_list{j} = cuts_list{j}.set_instrument(mi);
    cuts_list{j} = cuts_list{j}.set_sample(sample);
    plot(cuts_list{j}); lz 0 1; keep_figure; %[output:76f9c597]
end %[output:group:6c4996ce]
dir_name  = "GH";

dE_step = 2; %original energy transfer step data were binned to. No point in going finer
half_dE = 5; % half width of data binning

en_mm = cuts_list{1}.data.img_range(:,4);
en_mm(1) = max(min_Ei,en_mm(1));
%en_mm(1) = 100;
%en_mm(2) = 170;
cut_en = en_mm(1)+half_dE:2*half_dE:(en_mm(2)-half_dE);

cut_dimensions = 1;
GH_FFCutsFits.(selectCuts) = cuts_list;

GH_FFCutsFits = fit_multicutsFF_along_direction(... %[output:group:0668054c] %[output:756ececa] %[output:3c11d913] %[output:1b111b62] %[output:5fcc83f0] %[output:35b093cd] %[output:966756b8] %[output:62992502] %[output:2050d111] %[output:85870f62] %[output:70f6eb1f] %[output:531a3914] %[output:2896dbcb] %[output:3fe2c375] %[output:837d8cf2] %[output:9781a29c] %[output:25a8640f] %[output:980ee7cf] %[output:378a07c1] %[output:17d24f49] %[output:9a98e505] %[output:05ed5e85] %[output:0cc97390] %[output:0939db73] %[output:6ad48e3c] %[output:80792da3] %[output:1d89585d] %[output:808be484] %[output:8de114f1] %[output:771e38d9] %[output:214ef487] %[output:23db7ded] %[output:85b20da2] %[output:242cb736] %[output:9398eca3] %[output:33328826] %[output:6513fc2b] %[output:439f23a8] %[output:709edffd] %[output:6325e540] %[output:25ba5f47] %[output:6144bd39] %[output:33d3c855] %[output:37a53838] %[output:005ac302] %[output:02d21263] %[output:2c3d10d3] %[output:7a3788d2] %[output:136018fa] %[output:86589b6d] %[output:4c4ae2e7] %[output:2c57f651] %[output:688458c3] %[output:1e05aacf] %[output:7ae199d6] %[output:3ff6f7dc] %[output:0147d094] %[output:1bbed80f] %[output:46e9e9a2]
    GH_FFCutsFits,selectCuts,cut_dimensions,cut_en,dE_step,half_dE,true); %[output:group:0668054c] %[output:756ececa] %[output:3c11d913] %[output:1b111b62] %[output:5fcc83f0] %[output:35b093cd] %[output:966756b8] %[output:62992502] %[output:2050d111] %[output:85870f62] %[output:70f6eb1f] %[output:531a3914] %[output:2896dbcb] %[output:3fe2c375] %[output:837d8cf2] %[output:9781a29c] %[output:25a8640f] %[output:980ee7cf] %[output:378a07c1] %[output:17d24f49] %[output:9a98e505] %[output:05ed5e85] %[output:0cc97390] %[output:0939db73] %[output:6ad48e3c] %[output:80792da3] %[output:1d89585d] %[output:808be484] %[output:8de114f1] %[output:771e38d9] %[output:214ef487] %[output:23db7ded] %[output:85b20da2] %[output:242cb736] %[output:9398eca3] %[output:33328826] %[output:6513fc2b] %[output:439f23a8] %[output:709edffd] %[output:6325e540] %[output:25ba5f47] %[output:6144bd39] %[output:33d3c855] %[output:37a53838] %[output:005ac302] %[output:02d21263] %[output:2c3d10d3] %[output:7a3788d2] %[output:136018fa] %[output:86589b6d] %[output:4c4ae2e7] %[output:2c57f651] %[output:688458c3] %[output:1e05aacf] %[output:7ae199d6] %[output:3ff6f7dc] %[output:0147d094] %[output:1bbed80f] %[output:46e9e9a2]
cl = GH_FFCutsFits.(selectCuts);
GH_FFCutsFits.(selectCuts) = [cl{:}];

beep
beep
beep

all_fit_par = GH_FFCutsFits.([selectCuts,'_all_fit_par']);
bg_data = extract_bg_par(all_fit_par,[1,2]);
% original slope parameters
pd(bg_data(1));lx(all_fit_par(1).en,all_fit_par(end).en);keep_figure; %[output:4c4a0290]
pd(bg_data(2));lx(all_fit_par(1).en,all_fit_par(end).en);keep_figure %[output:5cb1b069]
%pd(bg_data(3));lx(fit_res.peak_fit_par(1).en,fit_res.peak_fit_par(end).en);keep_figure;
%pd(bg_data(4));lx(fit_res.peak_fit_par(1).en,fit_res.peak_fit_par(end).en);keep_figure
%%

doc = matlab.desktop.editor.getActive;
doc.save;
thisFile = 'e:\SHARE\Fe\Data\analysis\06_fit_with_AQ0\fit_cutFe_GH.m';
targ_file = fullfile(fileparts(thisFile),['fit_cutFe_GH_',selectCuts,'.pdf']);
export(thisFile,targ_file);

%%

fit_src_struc = GH_FFCutsFits;
save(CutFitFileGH,"fit_src_struc",'-v7.3');
close all;
%end

